<script setup>
import {computed,shallowRef} from 'vue';
import {store,actions} from '../store';
import AppIcon from './AppIcon.vue';
defineProps({collapsed:Boolean});const emit=defineEmits(['update:collapsed']);
const query=shallowRef('');
const counts=computed(()=>{const map=new Map();for(const file of store.files)map.set(file.partitionId,(map.get(file.partitionId)||0)+1);return map;});
const projects=computed(()=>store.partitions.filter(p=>!query.value||p.name.toLowerCase().includes(query.value.toLowerCase())));
function addNew(){const name=window.prompt('新建项目分区名称','');if(name?.trim())actions.addPartition(name);}
function rename(p){const name=window.prompt('修改项目名称',p.name);if(name?.trim())actions.renamePartition(p.id,name);}
function remove(p){const count=counts.value.get(p.id)||0;if(count&&!window.confirm(`项目“${p.name}”还有 ${count} 个文件，移除后文件会保留并转移到其他分区。继续？`))return;if(!actions.removePartition(p.id))window.alert('至少保留一个项目分区');}
</script>
<template><aside class="project-sidebar panel" :class="{collapsed}" aria-label="项目分区"><header><strong v-if="!collapsed">项目分区 <small>{{ store.partitions.length }}</small></strong><button type="button" class="collapse-button" :aria-label="collapsed?'展开项目列表':'收起项目列表'" @click="emit('update:collapsed',!collapsed)">{{ collapsed?'›':'‹' }}</button></header><div v-if="!collapsed" class="search"><input v-model="query" class="field-input" type="search" placeholder="搜索工地或楼栋" aria-label="搜索项目"/></div><button type="button" class="all-projects" :class="{active:store.activePartitionId==='all'}" title="全部项目" @click="actions.setActivePartition('all')"><AppIcon name="folder" :size="16"/><span v-if="!collapsed">全部项目</span><b>{{ store.files.length }}</b></button><nav class="project-list" aria-label="选择项目"><div v-for="p in projects" :key="p.id" class="project-row" :class="{active:store.activePartitionId===p.id}"><button type="button" class="project-select" :title="p.name" :aria-label="'选择项目 '+p.name" :aria-pressed="store.activePartitionId===p.id" @click="actions.setActivePartition(p.id)"><AppIcon name="folder" :size="15"/><span v-if="!collapsed" class="project-name">{{ p.name }}</span><b>{{ counts.get(p.id)||0 }}</b></button><details v-if="!collapsed" class="project-menu"><summary :aria-label="p.name+'的操作'">⋯</summary><div><button type="button" @click="rename(p)">重命名</button><button type="button" class="remove" @click="remove(p)">移除分区</button></div></details></div><p v-if="!projects.length&&!collapsed" class="empty-projects">没有匹配的项目</p></nav><button type="button" class="add-project" title="新建项目分区" @click="addNew">＋<span v-if="!collapsed">新建项目</span></button></aside></template>
<style scoped>
.project-sidebar{display:flex;flex-direction:column;position:sticky;top:12px;align-self:start;max-height:calc(100vh - 155px);min-width:0;padding:12px 0;background:var(--panel,#fff);color:var(--ink,#1f2329)}.project-sidebar header{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:0 12px 10px;font-size:14px}.project-sidebar small,.empty-projects{font-size:11px;color:#64748b}.collapse-button{border:1px solid var(--line,#e3e6ea);border-radius:5px;background:none;cursor:pointer;width:28px;height:28px;font-size:20px;color:inherit}.search{padding:0 12px 10px}.search input{font-size:12px;height:32px}.all-projects,.project-select{display:flex;align-items:center;gap:9px;border:0;background:none;text-align:left;cursor:pointer;font:inherit;color:inherit;min-width:0}.all-projects{margin:0 8px;padding:10px 8px;border-radius:6px;font-size:12px}.all-projects b,.project-select b{margin-left:auto;flex:none;min-width:20px;text-align:right;font-size:11px;font-weight:500;font-variant-numeric:tabular-nums;color:#64748b}.project-list{overflow:auto;scrollbar-gutter:stable;min-height:80px;padding:8px;display:grid;gap:4px}.project-row{display:flex;align-items:stretch;position:relative;border-radius:6px;border:1px solid transparent}.project-select{flex:1;padding:11px 8px;font-size:12px}.project-name{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;line-height:1.55;overflow-wrap:anywhere;flex:1}.project-row.active,.all-projects.active{background:var(--brand-soft,#e7f1fb);color:var(--brand,#1867c0)}.project-row.active{border-color:#bed6f0}.project-row:hover,.all-projects:hover{background:#f2f6fa}.project-menu{align-self:center;margin-right:3px}.project-menu summary{cursor:pointer;list-style:none;padding:8px 4px;color:#64748b;font-size:17px}.project-menu>div{position:absolute;right:4px;top:calc(100% - 5px);z-index:5;background:var(--panel,#fff);padding:5px;border:1px solid var(--line,#e3e6ea);border-radius:6px;box-shadow:0 5px 15px #23334d1a;min-width:110px}.project-menu button{display:block;width:100%;padding:7px;border:0;background:none;text-align:left;cursor:pointer;font:inherit;font-size:12px}.project-menu .remove{color:#b91c1c}.add-project{display:flex;justify-content:center;gap:8px;margin:8px 12px 0;border:1px dashed #a7bfd8;border-radius:6px;padding:9px;background:none;color:var(--brand,#1867c0);font:inherit;font-size:12px;cursor:pointer}.collapsed header{justify-content:center;padding-inline:4px}.collapsed .project-list{padding-inline:4px}.collapsed .project-select,.collapsed .all-projects{flex-direction:column;gap:5px;padding:10px 4px}.collapsed b{margin:0;min-width:0}.collapsed .add-project{margin-inline:8px}.project-select:focus-visible,.collapse-button:focus-visible,.add-project:focus-visible{outline:2px solid #1867c0;outline-offset:2px}@media(max-width:900px){.project-sidebar{position:static;max-height:270px}.project-list{grid-template-columns:repeat(2,minmax(0,1fr))}.collapsed .project-list{display:none}.collapsed .all-projects{flex-direction:row}.collapsed header{justify-content:flex-end}}@media(prefers-color-scheme:dark){.project-sidebar{background:#17202c;color:#e2e8f0}.project-menu>div{background:#17202c}.project-row:hover,.all-projects:hover{background:#243447}.project-row.active,.all-projects.active{background:#203c5c;color:#99c7f8}.search input{background:#17202c;color:#e2e8f0}}
</style>
